// ---------------------------------------------------------------------------

export class CHeraCompiler extends CFileHandler {

	get op() {
		return 'doCompileHera'
	}

	override notNeeded(
			path: string,
			hOptions: hash = {}
			): boolean {

		const destPath = withExt(path, '.ts')
		return (
			   !hOptions.force
			&& existsSync(destPath)
			&& newerDestFileExists(path, destPath)
			)
	}

	override async handle(
			path: string,
			hOptions: hash = {}
			): AutoPromise<TExecResult> {

		assert((fileExt(path) === '.hera'), "Not a hera file")
		const destPath = withExt(path, '.ts')
		if (!hOptions.force && existsSync(destPath)) {
			if (newerDestFileExists(path, destPath)) {
				return {
					success: true,
					notNeeded: true
					}
			}
		}

		try {
			const tempPath = withExt(path, '.temp.hera')
			const [heraCode, type] = await preprocessHeraFile(path, tempPath)
			const fileName = parsePath(path).fileName
			const tsCode = compileHera(heraCode, type, fileName)
			await Deno.writeTextFile(withExt(path, '.ts'), tsCode)

			return {
				success: true,
				stdout: tsCode
				}
		}

		catch (err) {
			const errMsg = `HERA COMPILE FAILED: ${pathStr(path)} - ${getErrStr(err)}`
			return {
				success: false,
				stdout: '',
				stderr: errMsg
				}
		}
	}
}

export const doCompileHera = new CHeraCompiler()

// ---------------------------------------------------------------------------

const buildHeraFile = (
		lMainCode: string[],
		lResetCode: string[],
		ruleSet: CRuleSet,
		type: THeraType,
		debug: boolean = false
		) => {

	const mainCode = mkCodeBlock(lMainCode, type)
	if (debug) {
		DUMP(mainCode, 'mainCode')
	}

	const resetCode = mkCodeBlock(lResetCode, type)
	if (debug) {
		DUMP(resetCode, 'resetCode')
	}

	const lRuleBlocks = ruleSet.lRules.map((rule) => rule.toString(type))
	if (debug) {
		let i1 = 0;for (const block of lRuleBlocks) {const i = i1++;
			DUMP(block, `Rule[${i}]`)
		}
	}

	let lParts: string[] = []
	lParts.push(
		"```",
		"import {CParseMatches} from 'parse-utils';",
		"export let pm = new CParseMatches();",
		"")
	if (nonEmpty(mainCode)) {
		lParts.push(mainCode, "")
	}

	lParts.push(
		"export const beginParse = (text: string): string? => {",
		indented(resetCode),
		indented('}'),
		"```",
		'',
		...lRuleBlocks)
	const result = lParts.join('\n').replaceAll('\t', spaces(2))
	if (debug) {
		DUMP(result, 'Result')
	}
	return result
}

// ---------------------------------------------------------------------------

export const unbalanced = (str: string): boolean => {

	if ( countChars(str, '(') !== countChars(str, ')') ) {
		return true
	}
	if ( countChars(str, '{') !== countChars(str, '}') ) {
		return true
	}
	return false
}

