export const preprocessHera = (
		contents: string,
		type: THeraType = 'typescript',
		debug: boolean = false
		): string => {

	const isComment = (str: string): boolean => {
		return toBool(str.match(/^\s*#\s/))
	}

	resetOneIndent()

	const lMainCode:  string[] = []
	const lResetCode: string[] = []

	const ruleSet = new CRuleSet()

	const iter = allLinesInBlock(contents).filter((x) => !isComment(x))
	const result = fromFSM(iter, [

		// 0 --- start
		//          until we see #beginParse(text), everything, including
		//          blank lines, goes into main code

		(line: string): TState => {
			if (line === '#beginParse(text)') {
				return 1
			}
			else {
				lMainCode.push(line)
				return 0
			}
		},

		// 1 --- in beginParse function
		//          until we see a rule name, everything, including
		//          blank lines, goes into reset code

		(line: string): TState => {
			const [level, str] = splitLine(line)
			if (nonEmpty(str) && (level === 0)) {
				ruleSet.addRule(str)
				return 2
			}
			else {
				if (isEmpty(str) && (level === 0)) {
					lResetCode.push('')
				}
				else {
					lResetCode.push(indented(str, level-1))
				}
				return 1
			}
		},

		// 2 --- have rule, want pattern
		//          skip blank lines, but expect a pattern at level 1

		(line: string, i: number): TState => {
			const [level, pat] = splitLine(line)
			if ((level === 0) && (pat === '')) {
				return 2
			}

			const rule = ruleSet.curRule()
			const name = rule.getName()
			const nb = rule.numBranches()
			assert((level === 1),
				`Expecting pattern for rule ${name}, branch ${nb} on line ${i}`)
			rule.addBranch(pat)
			return 3
		},

		// 3 --- have pattern, want code
		//          ignore blank lines

		(line: string, i: number): TState => {
			const [level, str] = splitLine(line)
			const rule = ruleSet.curRule()
			switch(level) {
				case 0: {
					if (str === '') {
						return 3
					}
					else {
						ruleSet.addRule(str)
						return 2
					}
				}
				case 1: {
					rule.addBranch(str)
					return 3
				}
				default: {
					const branch = rule.curBranch()

					// --- first line of code must be at level 2
					if (branch.numCodeLines() === 0) {
						assert((level === 2), "First line of code must be level 2")
						branch.addCode(`pm.match('${ruleSet.ruleName()}', $loc);`)
					}

					branch.addCode(indented(str, level-2))
					return 3
				}
			}
		}

		], {
			doneFunc: (state: TState): void => {
				if (state === 3) {
					const str = buildHeraFile(lMainCode, lResetCode, ruleSet, type, debug)
					throw str
				}
				else {
					croak(`Ended in state ${state}`)
				}
			}
			})
	assert((typeof result === 'string'), "result not a string")
	return result
}

// ---------------------------------------------------------------------------
// ASYNC

export const preprocessHeraFile = async (
		path: string,
		tempPath: (string | undefined) = undef
		): AutoPromise<[string, THeraType]> => {

	const [hMetaData, contents] = await openAndReadTextFile(path)
	const type = mdGet(hMetaData, 'type', 'civet')
	assert(isHeraType(type), `Bad hera type: ${type}`)
	const heraCode = preprocessHera(contents, type)
	if (defined(tempPath)) {
		await Deno.writeTextFile(tempPath, heraCode)
	}
	return [heraCode, type]
}

// ---------------------------------------------------------------------------
// ASYNC

export const testHeraCode = async (
		code: string,
		debug: boolean = false
		): AutoPromise<string> => {

	const path = barfTempFile(code, {ext: '.hera'})
	const [heraCode, type] = await preprocessHeraFile(path)

	// --- Make sure the generated code compiles
	try {
		compileHera(heraCode, type)
	}
	catch (err) {
		DUMP(heraCode, 'Hera Code', {lineNumbers: true})
		croak(`FAILED TO PARSE: ${getErrStr(err)}`)
	}

	return heraCode
}

